<script setup>
import {fmt} from '../domain'
defineProps({rows:Array,columns:Array,loading:Boolean});defineEmits(['open'])
const labels={name:'Phiếu',docstatus:'Trạng thái',farm:'Nông trường',farm_block:'Lô',farm_plot:'Thửa',crop_cycle:'Vụ',posting_date:'Ngày',harvest_date:'Ngày thu',received_date:'Ngày nhận',packing_date:'Ngày đóng gói',gross_weight_kg:'Kg thu',accepted_kg:'Kg đạt',rejected_kg:'Kg loại',input_kg:'Kg vào',output_kg:'Kg ra',stock_entry:'Phiếu kho',modified:'Cập nhật',status:'Trạng thái',approval_state:'Duyệt',supply_state:'Dự thu',resolved_percent:'% xử lý'}
</script>
<template><div class="table-scroll"><table><thead><tr><th v-for="column in columns" :key="column">{{labels[column]||column.replaceAll('_',' ')}}</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row.name||row.line||i" tabindex="0" @click="$emit('open',row)" @keydown.enter="$emit('open',row)"><td v-for="column in columns" :key="column"><span v-if="column==='docstatus'" class="pill" :class="'status-'+row.docstatus">{{['Nháp','Đã nộp','Đã hủy'][row.docstatus]}}</span><span v-else>{{fmt(row[column])}}</span></td></tr></tbody></table><p v-if="!rows?.length&&!loading" class="empty">Chưa có dữ liệu trong phạm vi này.</p><p v-if="loading" class="empty">Đang tải…</p></div></template>
